// src/App.js
import React from "react";
import { BrowserRouter as Router, Route, Switch } from "react-router-dom";
import LoginPage from "../src/pages/LoginPage";
import CompanyRegisterForm from "../src/pages/CompanyRegisterForm";
import JobCreatorDashboard from "../src/pages/JobCreatorDashboard";
import JobManagerDashboard from "../src/pages/CompanyRegisterForm";  // Assuming you have these pages

function App() {
  return (
    <Router>
      <div className="App">
        <Switch>
          <Route exact path="/" component={LoginPage} />
          <Route path="/register" component={CompanyRegisterForm} />
          <Route path="/job-creator-dashboard" component={JobCreatorDashboard} />
          <Route path="/job-manager-dashboard" component={JobManagerDashboard} />
          {/* Add other routes if necessary */}
        </Switch>
      </div>
    </Router>
  );
}

export default App;
